def submit(path: Path) -> None:
            try:
                propose_template(self.output, path)
            except BaseException as exc:  # pragma: no cover - surfaced below
                errors.append(exc)

def run(*arguments: str) -> subprocess.CompletedProcess[str]:
            return subprocess.run(
                [sys.executable, str(ckb), "template", *arguments],
                text=True,
                encoding="utf-8",
                errors="replace",
                stdout=subprocess.PIPE,
                stderr=subprocess.PIPE,
                check=False,
            )

def _source_context(target: str, purpose: str, key_entities: list[str] | None = None) -> dict[str, object]:
    return {
        "key_entities": key_entities or [],
        "links": [{"target": target, "purpose": purpose, "kind": "source"}],
        "current_facts": [],
    }
